// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: initialize and set MinSum to 1
        c.SetMinSum(1);
        c.Initialized();

        // Fund the user with 5 ether
        address user = address(0x123);
        vm.deal(user, 10 ether);
        vm.prank(user);
        c.Deposit{value: 5 ether}();

        // Now call Collect with _am = 5 ether (exactly the balance)
        // In reference: requires balances[user] >= _am (true), so it proceeds and balance becomes 0
        // In bug: requires balances[user] > _am (false), so it does nothing and balance stays 5 ether
        vm.prank(user);
        c.Collect(5 ether);

        // Assert that the reference behavior (balance == 0) holds; the bug would leave balance == 5 ether
        assertTrue(c.balances(user) == 0, "Balance should be zero after collecting full amount");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize contract
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund user1 with 100 wei and deposit it
        address user1 = address(0x1234);
        vm.deal(user1, 100);
        vm.prank(user1);
        c.Deposit{value: 100}();

        // Check balance before Collect
        assertEq(c.balances(user1), 100);

        // Try Collect with exact balance
        vm.prank(user1);
        c.Collect(100);

        // Assert: reference allows withdrawal (balance becomes 0), buggy rejects (balance stays 100)
        assertTrue(c.balances(user1) == 0);
    }
}

