pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup
        c.SetMinSum(0);
        c.Initialized();

        address user1 = address(0x123);
        address user2 = address(0x456);
        vm.deal(user1, 100 wei);
        vm.deal(user2, 50 wei);

        // user1 deposits 100
        vm.prank(user1);
        c.Deposit{value: 100}();

        // user2 deposits 50
        vm.prank(user2);
        c.Deposit{value: 50}();

        // user2 tries to collect 50
        vm.prank(user2);
        c.Collect(50);

        // Reference: balance becomes 0 (withdrawal succeeds)
        // Bug: balance stays 50 (withdrawal fails due to > check)
        uint256 balanceAfter = c.balances(user2);
        assertTrue(balanceAfter == 0, "Bug: balance should be 0 after collecting exactly equal amount");
    }
}

