// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 1 so Collect is possible
        c.SetMinSum(1);
        // Initialize so contract is ready
        c.Initialized();

        // depositor deposits 1 wei
        address depositor = address(0x1111);
        vm.deal(depositor, 1);
        vm.prank(depositor);
        c.Deposit{value: 1}();

        // A second user calls Collect(1) — this triggers a zero-value deposit via receive()
        // because the contract sends ether back to the caller, which then triggers receive() -> Deposit()
        address collector = address(0x2222);
        // We need to fund the contract so it can send 1 wei; also fund collector for gas
        vm.deal(collector, 0);
        // The contract's balance after depositor's deposit is 1 wei
        // Collector calls Collect(1)
        vm.prank(collector);
        c.Collect(1);

        // After Collect completes, the reference contract allows zero-value deposit (overflow guard passes),
        // so depositor's balance stays 1. The buggy contract rejects zero-value deposit,
        // so depositor's balance remains 0.
        assertTrue(c.balances(depositor) == 1);
    }
}

