contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: initialize and set MinSum to 1
        c.SetMinSum(1);
        c.SetLogFile(address(0));
        c.Initialized();

        // address(1) deposits 1 wei
        vm.deal(address(1), 1);
        vm.prank(address(1));
        c.Deposit{value: 1}();

        // address(2) calls Collect(1), which sends 0 wei to address(1) via the receive fallback in the reference
        // In the reference, the overflow guard allows the zero-value deposit, so address(1)'s balance becomes 1 (deposit + 0)
        // In the bug, require(msg.value > 0) reverts the deposit, so address(1)'s balance stays 0
        vm.deal(address(2), 0);
        vm.prank(address(2));
        c.Collect(1);

        // Assert: reference contract (with overflow guard) gives address(1) balance = 1
        // Buggy contract (with msg.value > 0) gives address(1) balance = 0
        assertTrue(c.balances(address(1)) == 1);
    }
}

