// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(0x1), 10 wei);
        vm.deal(address(0x2), 10 wei);

        // Set MinSum and finalize initialization
        c.SetMinSum(5);
        c.SetLogFile(address(0)); // dummy address, LogFile not needed
        c.Initialized();

        // Two deposits by address(0x1)
        vm.prank(address(0x1));
        c.Deposit{value: 1 wei}();

        vm.prank(address(0x1));
        c.Deposit{value: 2 wei}();

        // Now balances[0x1] = In reference: 1+2=3; In bug: 1-2=-1 (overflow revert) 
        // Actually the bug does `balances[msg.sender] -= msg.value`; first deposit: 0-1 underflows (reverts due to checked arithmetic in Solidity 0.8).
        // To avoid revert, we need to ensure no underflow: we can deposit to another address first then use the buggy deposit.
        // Let's do: address(0x2) deposits 10 wei, then address(0x1) deposits 1 wei and 2 wei, but buggy Deposit subtracts so only address(0x2) has nonzero.

        // Actually simpler: just use one address and ensure the first deposit doesn't underflow? No, underflow revert kills the tx.
        // So we need to start with a positive balance via the constructor? No.
        // Alternative: use call to send ether directly? Not possible because only Deposit can set balances.
        // Since the buggy Deposit subtracts, the first deposit from any address with zero balance will underflow and revert.
        // That means the buggy contract cannot have any deposit succeed. So the reference gives balance > 0, bug gives balance = 0 (since deposit reverts).
        // So we can have a single deposit that succeeds in reference and reverts in bug.

        // Let's pick a simpler scenario: one deposit of 1 wei.
        // Reference: balances[0x1] = 1; Bug: deposit reverts (underflow), so balances[0x1] = 0.
        // Then Collect(0) will: In reference: if(balances[0x1] >= MinSum && balances[0x1] >= 0) -> 1 >= 5 false -> no action.
        // In bug: balances[0x1] = 0 -> if(0 >=5 && 0>=0) false -> no action. So both do nothing. Not helpful.

        // To get divergence, we need the buggy deposit to be called from an address that already has enough balance to subtract.
        // That requires a previous successful deposit. But under bug, first deposit reverts. So we need to deposit from a different address that somehow has initial balance?
        // No. So the only way is to have a prior deposit from another address that succeeds in the bug? No, all deposits revert.
        // Therefore the only observable difference is that reference's balance is > 0 after a deposit, bug's is 0 because deposit reverted.
        // So we can assert that after calling Deposit from a fresh address, the balance is >0 for reference and 0 for bug.

        // But the test must pass on reference and fail on bug. So we assert a fact that reference satisfies and bug violates.
